    zh: { "Albania": "阿尔巴尼亚", "Kosovo": "科索沃", "Montenegro": "黑山", "England": "英格兰", "Colombia": "哥伦比亚", "Lesotho": "莱索托", "Ethiopia": "埃塞俄比亚", "Morocco": "摩洛哥" }
